const HEB_UNITS={"אפס":0,"אחד":1,"אחת":1,"שניים":2,"שתיים":2,"שני":2,"שתי":2,"שלושה":3,"שלוש":3,"ארבעה":4,"ארבע":4,"חמישה":5,"חמש":5,"שישה":6,"שש":6,"שבעה":7,"שבע":7,"שמונה":8,"תשעה":9,"תשע":9,"עשרה":10,"עשר":10,"אחד עשר":11,"אחת עשרה":11,"שנים עשר":12,"שתים עשרה":12,"עשרים":20,"שלושים":30,"ארבעים":40,"חמישים":50,"שישים":60,"שבעים":70,"שמונים":80,"תשעים":90};
function hebrewNumber(text){let t=String(text||"").replace(/-/g," ").replace(/\s+/g," ").trim();if(!t)return null;const direct=Number(t.replace(/,/g,""));if(Number.isFinite(direct))return direct;let total=0,current=0,used=false;const tokens=t.split(" ");for(let i=0;i<tokens.length;i++){let tok=tokens[i].replace(/^ו/,"");const pair=`${tok} ${tokens[i+1]||""}`;if(HEB_UNITS[pair]!=null){current+=HEB_UNITS[pair];i++;used=true;continue}if(HEB_UNITS[tok]!=null){current+=HEB_UNITS[tok];used=true;continue}if(tok==="מאה"){current+=(current?0:1)*100;used=true;continue}if(tok==="מאתיים"){current+=200;used=true;continue}if(tok==="מאות"){const prev=current||1;current=prev*100;used=true;continue}if(tok==="אלף"){total+=(current||1)*1000;current=0;used=true;continue}if(tok==="אלפיים"){total+=2000;used=true;continue}}return used?total+current:null}
function amountFromSpeech(text){const digit=String(text||"").match(/(?:₪\s*)?(-?\d{1,3}(?:,\d{3})*(?:\.\d+)?|-?\d+(?:\.\d+)?)\s*(?:₪|ש(?:קל|קלים)|שח)?/i);if(digit)return Math.abs(Number(digit[1].replace(/,/g,"")));const before=String(text||"").match(/((?:[א-ת]+\s+){0,5}[א-ת]+)\s+(?:שקל|שקלים|שח|₪)/i);return before?hebrewNumber(before[1]):null}
function cleanQuickText(text){let t=String(text||"");t=t.replace(/\b(?:היום|אתמול|שלשום|מחר)\b/g," ").replace(/\b(?:במזומן|מזומן|באשראי|אשראי|בביט|ביט|בהעברה|העברה)\b/g," ").replace(/(?:₪\s*)?\d[\d,.]*\s*(?:₪|שקל(?:ים)?|שח)?/gi," ").replace(/\b(?:אפס|אחד|אחת|שניים|שתיים|שני|שתי|שלושה|שלוש|ארבעה|ארבע|חמישה|חמש|שישה|שש|שבעה|שבע|שמונה|תשעה|תשע|עשרה|עשר|עשרים|שלושים|ארבעים|חמישים|שישים|שבעים|שמונים|תשעים|מאה|מאתיים|מאות|אלף|אלפיים)\b/g," ").replace(/\b(?:שקל|שקלים|שח)\b/g," ");t=t.replace(/\b(?:שילמתי|שילמנו|הוצאתי|הוצאה|קניתי|קנייה|הייתי|היה|עבור|לי|לה|לו|אז|נגיד)\b/g," ").replace(/^\s*(?:על|ב)\s+/g," ").replace(/\s+/g," ").trim().replace(/^[,.-]+|[,.-]+$/g,"");return t}
function historyCategory(cleaned,history){const q=normalizeMerchant(cleaned);if(q.length<2)return null;const qWords=q.split(" ").filter(w=>w.length>1);const matches=(history||[]).filter(x=>isExpense(x)&&x.category&&x.category!=="לא מסווג").map(x=>({x,n:normalizeMerchant(x.merchant)})).filter(({n})=>n&&(n===q||n.includes(q)||q.includes(n)||(qWords.length&&qWords.every(w=>n.includes(w)))));if(!matches.length&&qWords.length===1&&qWords[0].length>=3){const token=qWords[0];matches.push(...(history||[]).filter(x=>isExpense(x)&&x.category&&x.category!=="לא מסווג"&&normalizeMerchant(x.merchant).split(" ").includes(token)).map(x=>({x,n:normalizeMerchant(x.merchant)})))}if(!matches.length)return null;const counts=new Map();for(const {x} of matches)counts.set(x.category,(counts.get(x.category)||0)+1);const ranked=[...counts.entries()].sort((a,b)=>b[1]-a[1]);if(ranked.length>1&&ranked[0][1]===ranked[1][1])return null;return ranked[0][0]}
function quickCategory(text,cats,rules,history=[]){const cleaned=cleanQuickText(text);const n=normalizeMerchant(cleaned);const explicit=cats.find(c=>normalizeMerchant(c)&&n.includes(normalizeMerchant(c)));if(explicit)return explicit;const rule=[...rules].sort((a,b)=>String(b.merchant_key||"").length-String(a.merchant_key||"").length).find(r=>{const k=normalizeMerchant(r.merchant_key||r.merchant_label);return k&&(n.includes(k)||k.includes(n))});if(rule?.category)return rule.category;const learned=historyCategory(cleaned,history);if(learned&&cats.includes(learned))return learned;const guesses=[[/סופר|מכולת|רמי לוי|שופרסל|ויקטורי|אושר עד/,"סופר"],[/כלב|חתול|וטרינר|אוכל.*כלב|אוכל.*חתול/,"בעלי חיים"],[/מטפלת|בייביסיטר|גן ילדים|צהרון/,cats.includes("ילדים")?"ילדים":"אחר"],[/חשמל|גיחון|מים|גז|סופרגז|פזגז|אמישראגז/,"חשבונות"],[/דלק|חניה|חניון|כביש 6|מוסך/,"רכב ותחבורה"],[/מסעדה|קפה|וולט|wolt|תן ביס|משלוח/,"מסעדות ומשלוחים"],[/סופר פארם|בית מרקחת|תרופה|רופא|קופת חולים/,"בריאות"],[/נטפליקס|spotify|ספוטיפיי|youtube|יוטיוב|google one|מנוי/,"מנויים"],[/בגד|נעל|זארה|h&m/,"ביגוד"]];for(const [re,cat] of guesses)if(re.test(n)&&cats.includes(cat))return cat;return cats.includes("אחר")?"אחר":(cats[0]||"לא מסווג")}
function quickMerchant(text){return cleanQuickText(text)||"הוצאה ידנית"}
function splitQuickSpeech(text){const marked=String(text||"").replace(/\n+/g,". ").replace(/(שקל(?:ים)?|שח|₪)\s+(?=[^,;.])/g,"$1||| ");return marked.split(/\s*(?:\|\|\||,|;|\.| ואז | ואחר כך | בנוסף | וגם )\s*/).map(x=>x.trim()).filter(Boolean)}
function parseQuickExpenses(text,cats,rules,history=[]){return splitQuickSpeech(text).map((part,i)=>{const amount=amountFromSpeech(part);if(!amount)return null;const payment=/מזומן/.test(part)?"מזומן":/ביט/.test(part)?"ביט":/אשראי/.test(part)?"אשראי":/העברה/.test(part)?"העברה":"מזומן";const date=/שלשום/.test(part)?dateOffset(-2):/אתמול/.test(part)?dateOffset(-1):today();const merchant=quickMerchant(part);const category=quickCategory(part,cats,rules,history);return{_key:`q-${Date.now()}-${i}`,date,amount,category,merchant,payment_method:payment,notes:`הזנה מהירה: ${part}`}}).filter(Boolean)}

