 async function load(){setLoading(true);const{data:members,error:me}=await supabase.from("household_members").select("household_id").eq("user_id",session.user.id);if(me){setMsg(me.message);setLoading(false);return}if(!members?.length){setHome(null);setLoading(false);return}const hid=members[0].household_id;const[{data:h,error:he},{data:t,error:te},{data:c},{data:r},{data:b},{data:ib},{data:pl}]=await Promise.all([supabase.from("households").select("*").eq("id",hid).single(),supabase.from("transactions").select("*").eq("household_id",hid).order("date",{ascending:false}),supabase.from("categories").select("*").eq("household_id",hid),supabase.from("merchant_category_rules").select("*").eq("household_id",hid).order("merchant_label"),supabase.from("budgets").select("*").eq("household_id",hid),supabase.from("import_batches").select("*").eq("household_id",hid).order("created_at",{ascending:false}),supabase.from("planned_items").select("*").eq("household_id",hid).order("plan_date",{ascending:true})]);if(he||te){setMsg((he||te)?.message||"שגיאה בטעינת הנתונים");setLoading(false);return}setHome(h);setTx(t||[]);setCategoryRows(c||[]);setPrimaryOverride((c||[]).find(x=>x.is_primary)?.name||"");const savedCats=(c||[]).map(x=>x.name);const referencedCats=[...(t||[]).map(catName),...(r||[]).map(x=>x.category),...(b||[]).map(x=>x.category),...(pl||[]).map(x=>x.category)].filter(Boolean);setCats([...new Set([...(savedCats.length?savedCats:DEFAULT_CATS),...referencedCats,"לא מסווג"])]);setRules(r||[]);setBudgets(b||[]);setImports(ib||[]);setPlans(pl||[]);setSelectedIds(new Set());setLoading(false)}
 useEffect(()=>{load()},[]);
